// Compara el vector de la pregunta con el de cada ficha (similitud coseno)
const q = $('Embedding de la pregunta').first().json.embeddings[0];
const norma = v => Math.sqrt(v.reduce((s, x) => s + x * x, 0));
const nq = norma(q);
const UMBRAL = 0.30;      // por debajo, la ficha no tiene relación con la pregunta
const K = 3;              // máximo de fichas que se le pasan a la IA
const MAX_CHARS = 2400;   // límite de texto: la IA local lee ~40 palabras por segundo

const ordenadas = $input.all().map(it => {
  const e = JSON.parse(it.json.embedding);
  let dot = 0;
  for (let i = 0; i < e.length; i++) dot += e[i] * q[i];
  return { ...it.json, puntaje: dot / (nq * norma(e)) };
}).sort((a, b) => b.puntaje - a.puntaje);

const elegidas = [];
let largo = 0;
for (const f of ordenadas.slice(0, K)) {
  if (f.puntaje < UMBRAL) break;
  if (elegidas.length && largo + f.texto.length > MAX_CHARS) break;
  elegidas.push(f);
  largo += f.texto.length;
}

return [{ json: {
  pregunta: $('Recibir pregunta').first().json.pregunta,
  mejorPuntaje: Math.round((ordenadas[0]?.puntaje ?? 0) * 1000) / 1000,
  fichas: elegidas.map(f => ({ id: f.ficha_id, documento: f.documento, seccion: f.seccion, puntaje: Math.round(f.puntaje * 1000) / 1000 })),
  // fuente = secciones principales de las fichas casi tan parecidas como la mejor (margen 0,05)
  fuente: [...new Set(elegidas.filter(f => f.puntaje >= elegidas[0].puntaje - 0.05).map(f => `${f.documento} › ${f.seccion.split(' › ')[0].replace(/ \(parte \d+\)$/, '')}`))].join(' · '),
  contexto: elegidas.map(f => `[${f.documento} › ${f.seccion}]\n${f.texto}`).join('\n\n---\n\n'),
} }];
